# --- find tandem repeats: for each period, scan for runs of near-identical copies
def tandem(seq, minlen=12):
    n=len(seq); hits=[]
    for p in range(2, 80):
        i=0
        while i+p < n:
            # count how many contiguous copies match unit at i with <=20% mismatch
            unit=seq[i:i+p]
            count=1; j=i+p
            while j+p<=n:
                nxt=seq[j:j+p]
                mm=sum(a!=b for a,b in zip(unit,nxt))
                if mm<=max(1,p*0.2):
                    count+=1; j+=p
                else: break
            if count>=3:
                hits.append((i+1, j, p, count, seq[i:i+p]))
                i=j
            else:
                i+=1
    return hits

