import re
raw = open('region.fasta').read()
seq = ''.join(l.strip() for l in raw.split('\n')[1:] if l.strip()).upper()
n=len(seq)
code={}
bases='TCAG'; aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
i=0
for a in bases:
    for b in bases:
        for c in bases:
            code[a+b+c]=aas[i]; i+=1
def tr(s): return ''.join(code.get(s[j:j+3],'X') for j in range(0,len(s)-2,3))

# homopolymer runs >=5
print("Homopolymer runs >=5:")
for m in re.finditer(r'(A{5,}|T{5,}|G{5,}|C{5,})', seq):
    print(f"  {m.start()+1:5d}-{m.end():5d}  {m.group()}")

# simple di/tri repeats >=5 units
